967	    for (int idx = tid; idx < ldp * nb; idx += TPB) {
968	        int j = idx / ldp, rr = idx % ldp;
969	        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
970	    }
971	    __syncthreads();
972	}
973	
974	// Apply block reflector to the trailing submatrix. Every CTA grid-strides over
975	// COLUMN TILES of width CT; within a tile it does the WY update as two row-tiled
976	// GEMMs (V staged through smem in row strips of RB):
977	//   pass 1:  W  = V^T C          (W is nb x CT, accumulated across strips)
978	//            W' = T^T W
979	//   pass 2:  C -= V W'
980	// V = Acm[:, p:p+nb] (implicit unit diag, V[p+i,i]=1, zero above), rows >= p.
981	// CT trailing columns of C stay in global (read once in pass 1, read+written in
982	// pass 2). T (nb x nb upper-tri) and W/W' (nb x CT) live in smem.
983	template <int TPB, int NBMAX, int CT, int RB>
984	__device__ void coop_trailing_update(float* __restrict__ Acm, const float* __restrict__ Tg,
985	                                     float* dsmem, int n, int p, int nb) {
986	    const int tid = threadIdx.x;
987	    // partition dynamic smem
988	    float* Ts  = dsmem;                       // nb*nb   (col-major: Ts[l + i*nb])
989	    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT   (col-major: Ws[i + g*nb])
990	    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT   (col-major: Wps[i + g*nb])
991	    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb   (col-major: Vs[rr + i*RB])
992	    // cache T
993	    for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
994	    __syncthreads();
995	
996	    const int tstart = p + nb;
997	    for (int g0 = tstart + blockIdx.x * CT; g0 < n; g0 += gridDim.x * CT) {
998	        int ct = CT; if (g0 + ct > n) ct = n - g0;
999	
1000	        // ---- pass 1: W[i,g] = sum_{r>=p} V[r,i] C[r,g] ----
1001	        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
1002	        __syncthreads();
1003	        for (int r0 = p; r0 < n; r0 += RB) {
1004	            int rb = RB; if (r0 + rb > n) rb = n - r0;
1005	            // load V strip Vs[rr, i] = V[r0+rr, i]  (unit diag, zero above diag)
1006	            for (int idx = tid; idx < rb * nb; idx += TPB) {
1007	                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
1008	                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
1009	                Vs[rr + i * RB] = vv;
1010	            }
1011	            __syncthreads();
1012	            // each thread owns (i,g) pairs; accumulate over the strip's rows.
1013	            for (int idx = tid; idx < nb * ct; idx += TPB) {
1014	                int g = idx / nb, i = idx % nb;
1015	                const float* Cg = Acm + (size_t)(g0 + g) * n;
1016	                float acc = 0.f;
1017	                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cg[r0 + rr];
1018	                Ws[i + g * nb] += acc;
1019	            }
1020	            __syncthreads();
1021	        }
1022	        // ---- W' = T^T W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]  (double-buffered) ----
1023	        // negate W' so pass 2 does C += V*W'  (== C -= V W').
1024	        for (int idx = tid; idx < nb * ct; idx += TPB) {
1025	            int g = idx / nb, i = idx % nb;
1026	            float acc = 0.f;
1027	            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
1028	            Wps[i + g * nb] = -acc;
1029	        }
1030	        __syncthreads();
1031	        // ---- pass 2: C[r,g] += V[r,i] * W'[i,g] ----
1032	        for (int r0 = p; r0 < n; r0 += RB) {
1033	            int rb = RB; if (r0 + rb > n) rb = n - r0;
1034	            for (int idx = tid; idx < rb * nb; idx += TPB) {
1035	                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
1036	                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
1037	                Vs[rr + i * RB] = vv;
1038	            }
1039	            __syncthreads();
1040	            for (int idx = tid; idx < rb * ct; idx += TPB) {
1041	                int g = idx / rb, rr = idx % rb, r = r0 + rr;
1042	                float* Cg = Acm + (size_t)(g0 + g) * n;
1043	                float acc = 0.f;
1044	                int imax = r - p; if (imax >= nb) imax = nb - 1;
1045	                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
1046	                Cg[r] += acc;
1047	            }
1048	            __syncthreads();
1049	        }
1050	    }
1051	}
1052	
1053	template <int TPB, int NBMAX, int CT, int RB>
1054	__global__ void qr_coop_kernel(const float* __restrict__ A, float* __restrict__ Acm,
1055	                               float* __restrict__ H, float* __restrict__ tau,
1056	                               float* __restrict__ Tg, unsigned int* __restrict__ g_bar,
1057	                               int n, int gridSize) {
1058	    extern __shared__ float dsmem[];
1059	    const int tid = threadIdx.x;
1060	    const int gtid = blockIdx.x * TPB + tid;
1061	    const int gstride = gridDim.x * TPB;
1062	    unsigned int sense = 0u;
1063	
1064	    // row-major A -> column-major Acm (all CTAs)
1065	    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
1066	        int r = idx / n, c = idx % n;
1067	        Acm[(size_t)c * n + r] = A[(size_t)r * n + c];
1068	    }
1069	    coop_grid_barrier(g_bar, gridSize, sense);
1070	
1071	    for (int p = 0; p < n; p += NBMAX) {
1072	        int nb = NBMAX; if (p + nb > n) nb = n - p;
1073	        if (blockIdx.x == 0) coop_panel_factor<TPB, NBMAX>(Acm, Tg, tau, dsmem, n, p, nb);
1074	        coop_grid_barrier(g_bar, gridSize, sense);
1075	        coop_trailing_update<TPB, NBMAX, CT, RB>(Acm, Tg, dsmem, n, p, nb);
1076	        coop_grid_barrier(g_bar, gridSize, sense);
1077	    }
1078	
1079	    // column-major Acm -> row-major H (all CTAs)
1080	    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
1081	        int r = idx / n, c = idx % n;
1082	        H[(size_t)r * n + c] = Acm[(size_t)c * n + r];
1083	    }
1084	}
1085	
1086	template <int NBMAX, int CT, int RB>
1087	static size_t coop_smem_bytes(int n) {
1088	    // dynamic smem must cover BOTH the panel sub-panel (rows[p,n) x NBMAX, max at
1089	    // p=0 -> n*NBMAX) and the trailing-update buffers.
1090	    size_t panel = (size_t)n * NBMAX;
1091	    size_t trail = (size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX;
1092	    size_t fcount = panel > trail ? panel : trail;
1093	    return fcount * sizeof(float);
1094	}
1095	
1096	template <int TPB, int NBMAX, int CT, int RB>
1097	static int coop_max_grid(size_t sh) {
1098	    int blocks = 0;
1099	    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_coop_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
1100	    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
1101	    return blocks * sms;
1102	}
1103	
1104	template <int TPB, int NBMAX, int CT, int RB>
1105	static void coop_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
1106	                          unsigned int* g_bar, int n, int gridcap) {
1107	    size_t sh = coop_smem_bytes<NBMAX, CT, RB>(n);
1108	    cudaFuncSetAttribute(qr_coop_kernel<TPB, NBMAX, CT, RB>,
1109	                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)sh);
1110	    int maxg = coop_max_grid<TPB, NBMAX, CT, RB>(sh);
1111	    int grid = maxg; if (gridcap > 0 && gridcap < grid) grid = gridcap;
1112	    if (grid < 1) grid = 1;
1113	    qr_coop_kernel<TPB, NBMAX, CT, RB><<<grid, TPB, sh>>>(A, Acm, H, tau, Tg, g_bar, n, grid);
1114	}
