1116	void qr_coop_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
1117	                    int64_t Tg_ptr, int64_t gbar_ptr, int n, int NB, int gridcap) {
1118	    const float* A = reinterpret_cast<const float*>(A_ptr);
1119	    float* Acm = reinterpret_cast<float*>(Acm_ptr);
1120	    float* H = reinterpret_cast<float*>(H_ptr);
1121	    float* tau = reinterpret_cast<float*>(tau_ptr);
1122	    float* Tg = reinterpret_cast<float*>(Tg_ptr);
1123	    unsigned int* g_bar = reinterpret_cast<unsigned int*>(gbar_ptr);
1124	    const int TPB = 256;
1125	    const int CT = 32;       // trailing column-tile width per CTA
1126	    const int RB = 64;       // V row-strip height staged through smem
1127	    switch (NB) {
1128	        case 8:  coop_dispatch<TPB, 8,  CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
1129	        case 16: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
1130	        case 24: coop_dispatch<TPB, 24, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
1131	        case 32: coop_dispatch<TPB, 32, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
1132	        default: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
1133	    }
1134	}
