1136	// ===========================================================================
1137	// BATCHED TWO-KERNEL blocked QR for large n (n>1024), small batch B.
1138	//   The grid-barrier megakernel above is occupancy-limited to 12.5% because its
1139	//   per-block smem = n*NB (panel sub-panel) forces 1 block/SM EVEN for the
1140	//   trailing update (the dominant work). This version splits panel factor and
1141	//   trailing update into SEPARATE kernel launches (the launch boundary is the
1142	//   barrier -- NO cross-CTA atomics needed, capturable). The trailing kernel
1143	//   uses a tiny smem footprint -> high occupancy + a large grid; the panel
1144	//   kernel runs B blocks (one per matrix), so its big smem only costs B SMs.
1145	//   All B matrices are factored CONCURRENTLY (panel kernel = B blocks; trailing
1146	//   kernel grid-strides over (matrix, column-tile) work items).
1147	// Acm: column-major B*n*n. Tg: B*NBMAX*NBMAX compact-WY T. tau: B*n.
1148	// ===========================================================================
1149	
1150	// transpose row-major A (B,n,n) -> column-major Acm (per matrix Acm[b][c*n+r]).
1151	__global__ void qr_transpose_in(const float* __restrict__ A, float* __restrict__ Acm,
1152	                                int B, int n) {
1153	    const size_t total = (size_t)B * n * n;
1154	    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1155	         idx += (size_t)gridDim.x * blockDim.x) {
1156	        int b = idx / ((size_t)n * n);
1157	        size_t rem = idx - (size_t)b * n * n;
1158	        int r = rem / n, c = rem % n;
1159	        Acm[(size_t)b * n * n + (size_t)c * n + r] = A[(size_t)b * n * n + (size_t)r * n + c];
1160	    }
1161	}
1162	__global__ void qr_transpose_out(const float* __restrict__ Acm, float* __restrict__ H,
1163	                                 int B, int n) {
1164	    const size_t total = (size_t)B * n * n;
1165	    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1166	         idx += (size_t)gridDim.x * blockDim.x) {
1167	        int b = idx / ((size_t)n * n);
1168	        size_t rem = idx - (size_t)b * n * n;
1169	        int r = rem / n, c = rem % n;
1170	        H[(size_t)b * n * n + (size_t)r * n + c] = Acm[(size_t)b * n * n + (size_t)c * n + r];
1171	    }
1172	}
1173	
1174	// PANEL FACTOR kernel: grid = B (block b factors matrix b's panel [p,p+nb)).
1175	// Active sub-panel rows[p,n) x nb loaded into dynamic smem (ldp*nb floats,
1176	// sized by the host for this p), factored on-chip; reflectors+R written back to
1177	// Acm[b]; compact-WY T built into Tg[b]. Identical math to coop_panel_factor.
1178	// RM=false: Acm_all is column-major scratch, element(row p+rr,col p+j) at
1179	//   Acm[(p+j)*n + (p+rr)]. RM=true: Acm_all is row-major A IN PLACE (no
1180	//   transpose), element at A[(p+rr)*n + (p+j)] -- lets the trailing read row-major
1181	//   too, dropping both transpose kernels (~18% of n=512 time).
1182	template <int TPB, int NBMAX, bool RM = false>
1183	__global__ void qr_panel_kernel(float* __restrict__ Acm_all, float* __restrict__ Tg_all,
1184	                                float* __restrict__ tau_all, int B, int n, int p, int nb) {
1185	    extern __shared__ float Ps[];          // ldp * nb (col-major Ps[rr + j*ldp])
1186	    const int b = blockIdx.x;
1187	    if (b >= B) return;
1188	    float* Acm = Acm_all + (size_t)b * n * n;
1189	    float* Tg  = Tg_all + (size_t)b * NBMAX * NBMAX;
1190	    float* taub = tau_all + (size_t)b * n;
1191	
1192	    const int NWARP = TPB / 32;
1193	    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
1194	    __shared__ float red[REDSZ];
1195	    __shared__ float sval[4];
1196	    __shared__ float zsh[NBMAX];
1197	    __shared__ float taus[NBMAX];
1198	    const int tid = threadIdx.x;
1199	    const int lane = tid & 31, warp = tid >> 5;
1200	    const int ldp = n - p;
1201	
1202	    for (int idx = tid; idx < ldp * nb; idx += TPB) {
1203	        int j = idx / ldp, rr = idx % ldp;
1204	        size_t goff = RM ? ((size_t)(p + rr) * n + (p + j)) : ((size_t)(p + j) * n + (p + rr));
1205	        Ps[rr + j * ldp] = Acm[goff];
1206	    }
1207	    __syncthreads();
1208	
1209	    for (int j = 0; j < nb; ++j) {
1210	        float* pj = Ps + (size_t)j * ldp;
1211	        int rj = j;
1212	        float partial = 0.f;
1213	        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
1214	        // warp-shuffle reduce (1 sync instead of the log2(TPB)=8-sync tree): each
1215	        // warp reduces its partial, leaders write red[warp], thread 0 sums NWARP.
1216	        #pragma unroll
1217	        for (int o = 16; o > 0; o >>= 1) partial += __shfl_down_sync(0xffffffff, partial, o);
1218	        if (lane == 0) red[warp] = partial;
1219	        __syncthreads();
1220	        if (tid == 0) {
1221	            float nrm = 0.f;
1222	            for (int wi = 0; wi < NWARP; ++wi) nrm += red[wi];
1223	            float xnorm = sqrtf(nrm);
1224	            float alpha = pj[rj];
1225	            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
1226	            float tval, invden;
1227	            if (xnorm > 0.f && (alpha - beta) != 0.f) {
1228	                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
1229	            } else { tval = 0.f; invden = 0.f; beta = alpha; }
1230	            sval[0] = beta; sval[1] = tval; sval[2] = invden;
1231	        }
1232	        __syncthreads();
1233	        float beta = sval[0], tval = sval[1], invden = sval[2];
1234	        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
1235	        __syncthreads();
1236	        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
1237	        __syncthreads();
1238	        int ntrail = nb - (j + 1);
1239	        if (ntrail > 0) {
1240	            float pw[NBMAX];
1241	            #pragma unroll
1242	            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
1243	            for (int rr = rj + tid; rr < ldp; rr += TPB) {
1244	                float vr = pj[rr];
1245	                for (int t = 0; t < ntrail; ++t)
1246	                    pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
1247	            }
1248	            for (int t = 0; t < ntrail; ++t) {
1249	                float v = pw[t];
1250	                #pragma unroll
1251	                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
1252	                if (lane == 0) red[t * NWARP + warp] = v;
1253	            }
1254	            __syncthreads();
1255	            if (tid < ntrail) {
1256	                float w = 0.f;
1257	                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
1258	                zsh[tid] = tval * w;
1259	            }
1260	            __syncthreads();
1261	            for (int t = 0; t < ntrail; ++t) {
1262	                float tw = zsh[t];
1263	                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
1264	                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
1265	            }
1266	            __syncthreads();
1267	        }
1268	        if (tid == 0) pj[rj] = beta;
1269	        __syncthreads();
1270	    }
1271	    for (int i = tid; i < nb; i += TPB) { Tg[(size_t)i + (size_t)i * NBMAX] = taus[i]; taub[p + i] = taus[i]; }
1272	    __syncthreads();
1273	    for (int l = 1; l < nb; ++l) {
1274	        const float* Vl = Ps + (size_t)l * ldp;
1275	        float pz[NBMAX];
1276	        #pragma unroll
1277	        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
1278	        for (int rr = l + tid; rr < ldp; rr += TPB) {
1279	            float vl = (rr == l) ? 1.f : Vl[rr];
1280	            for (int i = 0; i < l; ++i) {
1281	                const float* Vi = Ps + (size_t)i * ldp;
1282	                float vi = (rr == i) ? 1.f : Vi[rr];
1283	                pz[i] += vi * vl;
1284	            }
1285	        }
1286	        for (int i = 0; i < l; ++i) {
1287	            float v = pz[i];
1288	            #pragma unroll
1289	            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
1290	            if (lane == 0) red[i * NWARP + warp] = v;
1291	        }
1292	        __syncthreads();
1293	        if (tid < l) {
1294	            float zz = 0.f;
1295	            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
1296	            zsh[tid] = zz;
1297	        }
1298	        __syncthreads();
1299	        float tl = taus[l];
1300	        for (int i = tid; i < l; i += TPB) {
1301	            float acc = 0.f;
1302	            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
1303	            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
1304	        }
1305	        __syncthreads();
1306	    }
1307	    for (int idx = tid; idx < ldp * nb; idx += TPB) {
1308	        int j = idx / ldp, rr = idx % ldp;
1309	        size_t goff = RM ? ((size_t)(p + rr) * n + (p + j)) : ((size_t)(p + j) * n + (p + rr));
1310	        Acm[goff] = Ps[rr + j * ldp];
1311	    }
1312	}
1313	
1314	// TRAILING kernel: grid-strides over (matrix b, column-tile g0) work items.
1315	// Small smem (Ts + Ws + Wps + Vs) -> high occupancy, large grid. For each work
1316	// item applies the block reflector to CT trailing columns of matrix b:
1317	//   W = V^T C ; W' = T^T W ; C -= V W'  (V staged through smem in RB-row strips).
1318	template <int TPB, int NBMAX, int CT, int RB>
1319	__global__ void qr_trailing_kernel(float* __restrict__ Acm_all, const float* __restrict__ Tg_all,
1320	                                   int B, int n, int p, int nb) {
1321	    extern __shared__ float dsmem[];
1322	    float* Ts  = dsmem;                       // nb*nb
1323	    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT
1324	    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT
1325	    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb
1326	    float* Cs  = Vs + (size_t)RB * NBMAX;     // RB*CT (C strip, col-major Cs[rr+g*RB])
1327	    const int tid = threadIdx.x;
1328	
1329	    const int tstart = p + nb;
1330	    const int ntiles = (n - tstart + CT - 1) / CT;   // column tiles per matrix
1331	    if (ntiles <= 0) return;
1332	    const long totwork = (long)B * ntiles;
1333	
1334	    for (long widx = blockIdx.x; widx < totwork; widx += gridDim.x) {
1335	        int b = widx / ntiles;
1336	        int tileIdx = widx - (long)b * ntiles;
1337	        int g0 = tstart + tileIdx * CT;
1338	        int ct = CT; if (g0 + ct > n) ct = n - g0;
1339	        float* Acm = Acm_all + (size_t)b * n * n;
1340	        const float* Tg = Tg_all + (size_t)b * NBMAX * NBMAX;
1341	
1342	        // cache T for this matrix
1343	        for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
1344	        __syncthreads();
1345	
1346	        // pass 1: W = V^T C. Stage BOTH V and C strips into smem so each C
1347	        // element is read from global ONCE per strip (was read nb times).
1348	        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
1349	        __syncthreads();
1350	        for (int r0 = p; r0 < n; r0 += RB) {
1351	            int rb = RB; if (r0 + rb > n) rb = n - r0;
1352	            for (int idx = tid; idx < rb * nb; idx += TPB) {
1353	                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
1354	                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
1355	                Vs[rr + i * RB] = vv;
1356	            }
1357	            for (int idx = tid; idx < rb * ct; idx += TPB) {
1358	                int g = idx / rb, rr = idx % rb;
1359	                Cs[rr + g * RB] = Acm[(size_t)(g0 + g) * n + (r0 + rr)];
1360	            }
1361	            __syncthreads();
1362	            for (int idx = tid; idx < nb * ct; idx += TPB) {
1363	                int g = idx / nb, i = idx % nb;
1364	                float acc = 0.f;
1365	                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cs[rr + g * RB];
1366	                Ws[i + g * nb] += acc;
1367	            }
1368	            __syncthreads();
1369	        }
1370	        // W' = -T^T W
1371	        for (int idx = tid; idx < nb * ct; idx += TPB) {
1372	            int g = idx / nb, i = idx % nb;
1373	            float acc = 0.f;
1374	            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
1375	            Wps[i + g * nb] = -acc;
1376	        }
1377	        __syncthreads();
1378	        // pass 2: C += V W'
1379	        for (int r0 = p; r0 < n; r0 += RB) {
1380	            int rb = RB; if (r0 + rb > n) rb = n - r0;
1381	            for (int idx = tid; idx < rb * nb; idx += TPB) {
1382	                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
1383	                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
1384	                Vs[rr + i * RB] = vv;
1385	            }
1386	            __syncthreads();
1387	            for (int idx = tid; idx < rb * ct; idx += TPB) {
1388	                int g = idx / rb, rr = idx % rb, r = r0 + rr;
1389	                float* Cg = Acm + (size_t)(g0 + g) * n;
1390	                float acc = 0.f;
1391	                int imax = r - p; if (imax >= nb) imax = nb - 1;
1392	                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
1393	                Cg[r] += acc;
1394	            }
1395	            __syncthreads();
1396	        }
1397	    }
1398	}
