1408	template <int TPB, int NBMAX, int CT, int RB>
1409	static void coop2_run(float* Acm, float* Tg, float* tau, int B, int n) {
1410	    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
1411	    // trailing kernel smem: Ts + Ws + Wps + Vs + Cs (C strip staged for pass1).
1412	    size_t trail_sh = ((size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT
1413	                       + (size_t)RB * NBMAX + (size_t)RB * CT) * sizeof(float);
1414	    int tgrid = trailing_max_grid<TPB, NBMAX, CT, RB>(trail_sh);
1415	    if (tgrid < 1) tgrid = sms;
1416	    // panel kernel: dynamic smem ldp*nb (sized per p); cap to device opt-in.
1417	    cudaFuncSetAttribute(qr_panel_kernel<TPB, NBMAX>,
1418	                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)((size_t)n * NBMAX * sizeof(float)));
1419	    for (int p = 0; p < n; p += NBMAX) {
1420	        int nb = NBMAX; if (p + nb > n) nb = n - p;
1421	        size_t panel_sh = (size_t)(n - p) * nb * sizeof(float);
1422	        qr_panel_kernel<TPB, NBMAX><<<B, TPB, panel_sh>>>(Acm, Tg, tau, B, n, p, nb);
1423	        if (p + nb < n)
1424	            qr_trailing_kernel<TPB, NBMAX, CT, RB><<<tgrid, TPB, trail_sh>>>(Acm, Tg, B, n, p, nb);
1425	    }
1426	}
