1516	// ===========================================================================
1517	// TWO-LEVEL panel for the batched scheme: factor a WIDE panel of width NB using
1518	// inner sub-blocks of width IB (each held in smem at (n-ps)*IB, which fits even
1519	// when (n-p)*NB would not). This decouples the trailing block width NB (which we
1520	// want LARGE -> the trailing update re-reads C n/NB times, so HBM traffic ~1/NB)
1521	// from the smem limit. The panel kernel still runs B blocks, so its cost is on
1522	// B SMs; the wide T is built from the global reflectors. The same trailing
1523	// kernel then runs with the large NB.
1524	// ===========================================================================
1525	
1526	// Factor inner sub-block [ps,ps+ib) (cols local 0..ib-1) of matrix Acm, holding
1527	// rows[ps,n) x ib in smem Ps; write reflectors+R back to Acm; fill the IB-block
1528	// diagonal of the wide T (Tg col-major, NBMAX-leading) at columns [ps-p..].
1529	template <int TPB, int IB, int NBMAX>
1530	__device__ void wpanel_inner_factor(float* __restrict__ Acm, float* __restrict__ Tg,
1531	                                    float* __restrict__ taub, float* Ps,
1532	                                    float* red, float* sval, float* zsh, float* taus,
1533	                                    int n, int p, int ps, int ib) {
1534	    const int NWARP = TPB / 32;
1535	    const int tid = threadIdx.x;
1536	    const int lane = tid & 31, warp = tid >> 5;
1537	    const int ldp = n - ps;
1538	    for (int idx = tid; idx < ldp * ib; idx += TPB) {
1539	        int j = idx / ldp, rr = idx % ldp;
1540	        Ps[rr + j * ldp] = Acm[(size_t)(ps + j) * n + (ps + rr)];
1541	    }
1542	    __syncthreads();
1543	    for (int j = 0; j < ib; ++j) {
1544	        float* pj = Ps + (size_t)j * ldp;
1545	        int rj = j;
1546	        float partial = 0.f;
1547	        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
1548	        red[tid] = partial; __syncthreads();
1549	        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
1550	        if (tid == 0) {
1551	            float xnorm = sqrtf(red[0]);
1552	            float alpha = pj[rj];
1553	            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
1554	            float tval, invden;
1555	            if (xnorm > 0.f && (alpha - beta) != 0.f) { tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta); }
1556	            else { tval = 0.f; invden = 0.f; beta = alpha; }
1557	            sval[0] = beta; sval[1] = tval; sval[2] = invden;
1558	        }
1559	        __syncthreads();
1560	        float beta = sval[0], tval = sval[1], invden = sval[2];
1561	        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
1562	        __syncthreads();
1563	        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
1564	        __syncthreads();
1565	        int ntrail = ib - (j + 1);
1566	        if (ntrail > 0) {
1567	            float pw[IB];
1568	            #pragma unroll
1569	            for (int t = 0; t < IB; ++t) pw[t] = 0.f;
1570	            for (int rr = rj + tid; rr < ldp; rr += TPB) {
1571	                float vr = pj[rr];
1572	                for (int t = 0; t < ntrail; ++t) pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
1573	            }
1574	            for (int t = 0; t < ntrail; ++t) {
1575	                float v = pw[t];
1576	                #pragma unroll
1577	                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
1578	                if (lane == 0) red[t * NWARP + warp] = v;
1579	            }
1580	            __syncthreads();
1581	            if (tid < ntrail) { float w = 0.f; for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi]; zsh[tid] = tval * w; }
1582	            __syncthreads();
1583	            for (int t = 0; t < ntrail; ++t) {
1584	                float tw = zsh[t];
1585	                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
1586	                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
1587	            }
1588	            __syncthreads();
1589	        }
1590	        if (tid == 0) pj[rj] = beta;
1591	        __syncthreads();
1592	    }
1593	    // diagonal IB-block of wide T (recurrence within the inner block, V from smem)
1594	    int co = ps - p;     // wide-column offset of this inner block
1595	    for (int i = tid; i < ib; i += TPB) { Tg[(size_t)(co + i) + (size_t)(co + i) * NBMAX] = taus[i]; taub[ps + i] = taus[i]; }
1596	    __syncthreads();
1597	    for (int l = 1; l < ib; ++l) {
1598	        const float* Vl = Ps + (size_t)l * ldp;
1599	        float pz[IB];
1600	        #pragma unroll
1601	        for (int t = 0; t < IB; ++t) pz[t] = 0.f;
1602	        for (int rr = l + tid; rr < ldp; rr += TPB) {
1603	            float vl = (rr == l) ? 1.f : Vl[rr];
1604	            for (int i = 0; i < l; ++i) { const float* Vi = Ps + (size_t)i * ldp; float vi = (rr == i) ? 1.f : Vi[rr]; pz[i] += vi * vl; }
1605	        }
1606	        for (int i = 0; i < l; ++i) { float v = pz[i]; for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o); if (lane == 0) red[i * NWARP + warp] = v; }
1607	        __syncthreads();
1608	        if (tid < l) { float zz = 0.f; for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi]; zsh[tid] = zz; }
1609	        __syncthreads();
1610	        float tl = taus[l];
1611	        for (int i = tid; i < l; i += TPB) {
1612	            float acc = 0.f;
1613	            for (int m = i; m < l; ++m) acc += Tg[(size_t)(co + i) + (size_t)(co + m) * NBMAX] * zsh[m];
1614	            Tg[(size_t)(co + i) + (size_t)(co + l) * NBMAX] = -tl * acc;
1615	        }
1616	        __syncthreads();
1617	    }
1618	    // write factored inner sub-panel back to global Acm
1619	    for (int idx = tid; idx < ldp * ib; idx += TPB) {
1620	        int j = idx / ldp, rr = idx % ldp;
1621	        Acm[(size_t)(ps + j) * n + (ps + rr)] = Ps[rr + j * ldp];
1622	    }
1623	    __syncthreads();
1624	}
