1626	// Apply inner block's IB reflectors (just-factored, in global Acm cols
1627	// [ps,ps+ib), rows>=ps, implicit unit diag) to wide-panel columns [c0,c1) in
1628	// global Acm: C -= V (Tib^T (V^T C)). Tib is the IB-diagonal block of Tg.
1629	// Uses smem buffers Wbuf (ib*wcols) and Vbuf (RB*ib).
1630	template <int TPB, int IB, int NBMAX, int RB>
1631	__device__ void wpanel_apply_inner(float* __restrict__ Acm, const float* __restrict__ Tg,
1632	                                   float* Wbuf, float* Vbuf, float* Tib,
1633	                                   int n, int p, int ps, int ib, int c0, int c1) {
1634	    const int tid = threadIdx.x;
1635	    int wcols = c1 - c0;
1636	    if (wcols <= 0) return;
1637	    int co = ps - p;
1638	    // cache Tib (ib x ib upper-tri) contiguous Tib[l + i*ib]
1639	    for (int idx = tid; idx < ib * ib; idx += TPB) Tib[idx] = Tg[(size_t)(co + idx % ib) + (size_t)(co + idx / ib) * NBMAX];
1640	    __syncthreads();
1641	    // W = V^T C  (ib x wcols)
1642	    for (int idx = tid; idx < ib * wcols; idx += TPB) Wbuf[idx] = 0.f;
1643	    __syncthreads();
1644	    for (int r0 = ps; r0 < n; r0 += RB) {
1645	        int rb = RB; if (r0 + rb > n) rb = n - r0;
1646	        for (int idx = tid; idx < rb * ib; idx += TPB) {
1647	            int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = ps + i;
1648	            float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
1649	            Vbuf[rr + i * RB] = vv;
1650	        }
1651	        __syncthreads();
1652	        for (int idx = tid; idx < ib * wcols; idx += TPB) {
1653	            int g = idx / ib, i = idx % ib;
1654	            const float* Cg = Acm + (size_t)(c0 + g) * n;
1655	            float acc = 0.f;
1656	            for (int rr = 0; rr < rb; ++rr) acc += Vbuf[rr + i * RB] * Cg[r0 + rr];
1657	            Wbuf[i + g * ib] += acc;
1658	        }
1659	        __syncthreads();
1660	    }
1661	    // W' = -Tib^T W (overwrite into Wbuf' region? reuse: store into same Wbuf after read)

file.content:
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    // ---- write factored sub-panel back to global Acm (rows [p,n), cols [p,p+nb)) ----
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
    }
    __syncthreads();
