    // need a second buffer; pack W' right after W in Wbuf is not possible in-place per-col.
    // We do it per (i,g) reading all l (W still intact), writing to a temp then copy.
    // Simpler: compute W'[i,g] into registers row-by-row is hard; use Vbuf-adjacent? Instead
    // we negate-and-transform in place column by column: for each g, Wp[i]=sum_{l<=i}Tib[l,i]W[l,g].
    // Since Wp[i] depends only on W[l<=i,g] (same column), we can compute top-down into a small
    // per-thread array when one thread owns a whole column. Assign columns to threads:
    for (int g = tid; g < wcols; g += TPB) {
        float wcol[IB];
        for (int i = 0; i < ib; ++i) wcol[i] = Wbuf[i + g * ib];
        float wp[IB];
        for (int i = 0; i < ib; ++i) { float acc = 0.f; for (int l = 0; l <= i; ++l) acc += Tib[l + i * ib] * wcol[l]; wp[i] = -acc; }
        for (int i = 0; i < ib; ++i) Wbuf[i + g * ib] = wp[i];
    }
    __syncthreads();
    // C += V W'
    for (int r0 = ps; r0 < n; r0 += RB) {
        int rb = RB; if (r0 + rb > n) rb = n - r0;
        for (int idx = tid; idx < rb * ib; idx += TPB) {
            int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = ps + i;
            float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
            Vbuf[rr + i * RB] = vv;
        }
        __syncthreads();
        for (int idx = tid; idx < rb * wcols; idx += TPB) {
            int g = idx / rb, rr = idx % rb, r = r0 + rr;
            float* Cg = Acm + (size_t)(c0 + g) * n;
            float acc = 0.f;
            int imax = r - ps; if (imax >= ib) imax = ib - 1;
            for (int i = 0; i <= imax; ++i) acc += Vbuf[rr + i * RB] * Wbuf[i + g * ib];
            Cg[r] += acc;
        }
        __syncthreads();
    }
}

// Build the FULL wide NB x NB compact-WY T from scratch, reading the reflector
// panel V (cols [p,p+nb), rows>=p) from GLOBAL Acm (V[p+i,i] implicit 1; the
// stored diagonal Acm[(p+i)*n+(p+i)] holds R's beta, treated as 1 here).
// Standard dlarft recurrence: T[l,l]=tau_l; for i<l, z[i]=V[:,i]^T V[:,l],
// T[0:l,l] = -tau_l * (T[0:l,0:l] @ z). taus_wide holds tau for cols [p,p+nb).
template <int TPB, int NBMAX>
__device__ void wpanel_build_T(float* __restrict__ Acm, float* __restrict__ Tg,
                               const float* __restrict__ taus_wide,
                               float* red, float* zsh,
                               int n, int p, int nb) {
    const int NWARP = TPB / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    for (int i = tid; i < nb; i += TPB) Tg[(size_t)i + (size_t)i * NBMAX] = taus_wide[i];
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        const float* Vl = Acm + (size_t)(p + l) * n;   // V column l in global
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        // z[i] = sum_{r>p+l} V[r,i]*V[r,l]  over STRICTLY-below-diagonal rows
        //   (the diagonal r==p+l term, where V[p+l,l]=1 implicitly, is added
        //   separately below as V[p+l,i]*1 -- do NOT read Acm[(p+l)*n+(p+l)],
        //   which holds R's beta, not 1).
        for (int r = p + l + 1 + tid; r < n; r += TPB) {
            float vl = Vl[r];                          // r>p+l -> real reflector entry
            for (int i = 0; i < l; ++i) {
                const float* Vi = Acm + (size_t)(p + i) * n;
                pz[i] += Vi[r] * vl;                   // r>p+i always (r>p+l>p+i)
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zz += Acm[(size_t)(p + tid) * n + (p + l)]; // r==p+l term: V[p+l,i]*V[p+l,l]=V[p+l,tid]*1
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taus_wide[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
}

// WIDE PANEL kernel: grid=B. Block b factors matrix b's NB-wide panel [p,p+nb)
// via IB-wide inner sub-blocks (each resident in smem at (n-ps)*IB), applying
// each inner block's reflectors to the remaining wide-panel columns, then builds
// the full NB-wide T. dsmem must hold max((n-p)*IB, ib*NBwide + RB*IB) floats.
template <int TPB, int IB, int NBMAX, int RB>
__global__ void qr_wpanel_kernel(float* __restrict__ Acm_all, float* __restrict__ Tg_all,
                                 float* __restrict__ tau_all, int B, int n, int p, int nb) {
    extern __shared__ float dsm[];
    const int b = blockIdx.x;
    if (b >= B) return;
    float* Acm = Acm_all + (size_t)b * n * n;
    float* Tg  = Tg_all + (size_t)b * NBMAX * NBMAX;
    float* taub = tau_all + (size_t)b * n;
    const int NWARP = TPB / 32;
    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    __shared__ float taus[IB];
    const int tid = threadIdx.x;

    for (int ps = p; ps < p + nb; ps += IB) {
        int ib = IB; if (ps + ib > p + nb) ib = p + nb - ps;
        // factor inner sub-block in smem (dsm holds (n-ps)*ib)
        wpanel_inner_factor<TPB, IB, NBMAX>(Acm, Tg, taub, dsm, red, sval, zsh, taus, n, p, ps, ib);
        __syncthreads();
        // apply this inner block to the remaining wide-panel columns [ps+ib, p+nb)
        int c0 = ps + ib, c1 = p + nb;
        if (c1 > c0) {
            // dsm layout for apply: Wbuf[ib*wcols] then Vbuf[RB*ib]; Tib in zsh-adjacent? use red? need separate.
            float* Wbuf = dsm;                       // ib * (NB) max
            float* Vbuf = Wbuf + (size_t)IB * NBMAX; // RB * IB
            float* Tib  = Vbuf + (size_t)RB * IB;    // IB * IB
            wpanel_apply_inner<TPB, IB, NBMAX, RB>(Acm, Tg, Wbuf, Vbuf, Tib, n, p, ps, ib, c0, c1);
            __syncthreads();
        }
    }
    // build full NB-wide T from global reflectors (taub[p..p+nb) holds taus)
    // copy taus into a contiguous smem? wpanel_build_T reads taus_wide via global taub+p.
    wpanel_build_T<TPB, NBMAX>(Acm, Tg, taub + p, red, zsh, n, p, nb);
}

// driver for the two-level wide-panel variant.
template <int TPB, int NBMAX, int IB, int CT, int RB>
static void coop3_run(float* Acm, float* Tg, float* tau, int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    size_t trail_sh = ((size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX) * sizeof(float);
    int tgrid = trailing_max_grid<TPB, NBMAX, CT, RB>(trail_sh);
    if (tgrid < 1) tgrid = sms;
    // wide-panel smem: max((n-p)*IB, IB*NBMAX + RB*IB + IB*IB)
    size_t wsh_max = (size_t)n * IB;
    size_t wsh_apply = (size_t)IB * NBMAX + (size_t)RB * IB + (size_t)IB * IB;
    if (wsh_apply > wsh_max) wsh_max = wsh_apply;
    wsh_max *= sizeof(float);
    cudaFuncSetAttribute(qr_wpanel_kernel<TPB, IB, NBMAX, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)wsh_max);
    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        size_t wsh = (size_t)(n - p) * IB;
        if (wsh_apply > wsh) wsh = wsh_apply;
        wsh *= sizeof(float);
        qr_wpanel_kernel<TPB, IB, NBMAX, RB><<<B, TPB, wsh>>>(Acm, Tg, tau, B, n, p, nb);
        if (p + nb < n)
            qr_trailing_kernel<TPB, NBMAX, CT, RB><<<tgrid, TPB, trail_sh>>>(Acm, Tg, B, n, p, nb);
    }
}

template <int TPB, int NBMAX, int IB, int CT, int RB>
static void coop3_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                           int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    int cgrid = sms * 4;
    qr_transpose_in<<<cgrid, TPB>>>(A, Acm, B, n);
    coop3_run<TPB, NBMAX, IB, CT, RB>(Acm, Tg, tau, B, n);
    qr_transpose_out<<<cgrid, TPB>>>(Acm, H, B, n);
}

void qr_coop3_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                     int64_t Tg_ptr, int B, int n, int NB) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    const int TPB = 256;
    const int IB = 8;
    const int CT = 32;
    const int RB = 64;
    switch (NB) {
        case 16: coop3_dispatch<TPB, 16, IB, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 32: coop3_dispatch<TPB, 32, IB, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 48: coop3_dispatch<TPB, 48, IB, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 64: coop3_dispatch<TPB, 64, IB, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        default: coop3_dispatch<TPB, 32, IB, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
    }
}

// Single WIDE-panel factor (two-level: IB=8 inner sub-blocks held in smem so a
// wide NB panel fits even when (n-p)*NB would overflow) -- used for n=4096 where
// the flat panel kernel's (n-p)*NB smem exceeds the 227KB opt-in. Produces the
// full NB-wide compact-WY T in Tg, exactly the layout the Triton tf32x3 trailing
// consumes. Defined here, after qr_wpanel_kernel.
template <int TPB, int IB, int NBMAX, int RB>
static void coop2_wpanel_one(float* Acm, float* Tg, float* tau, int B, int n, int p, int nb) {
    size_t wsh_max = (size_t)n * IB;
    size_t wsh_apply = (size_t)IB * NBMAX + (size_t)RB * IB + (size_t)IB * IB;
    if (wsh_apply > wsh_max) wsh_max = wsh_apply;
    cudaFuncSetAttribute(qr_wpanel_kernel<TPB, IB, NBMAX, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)(wsh_max * sizeof(float)));
    size_t wsh = (size_t)(n - p) * IB;
    if (wsh_apply > wsh) wsh = wsh_apply;
    qr_wpanel_kernel<TPB, IB, NBMAX, RB><<<B, TPB, wsh * sizeof(float)>>>(Acm, Tg, tau, B, n, p, nb);
}
void qr_coop2_wpanel(int64_t Acm_ptr, int64_t Tg_ptr, int64_t tau_ptr,
                     int B, int n, int NB, int p, int nb) {
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    const int IB = 8, RB = 64;
    switch (NB) {
        case 16: coop2_wpanel_one<TPB, IB, 16, RB>(Acm, Tg, tau, B, n, p, nb); break;
        case 32: coop2_wpanel_one<TPB, IB, 32, RB>(Acm, Tg, tau, B, n, p, nb); break;
        default: coop2_wpanel_one<TPB, IB, 16, RB>(Acm, Tg, tau, B, n, p, nb); break;
    }
}
"""

_CUDA_CPP = r"""
