# cfg index -> (NB, CT). Must mirror the C++ switch in qr_blocked_launch.
_BLOCKED_CFG = {
    0: (32, 64), 1: (48, 48), 2: (64, 32), 3: (64, 24), 4: (32, 96),
    5: (16, 128), 6: (16, 32), 7: (16, 16), 8: (24, 24), 9: (16, 64),
    10: (8, 64), 11: (16, 48),
}


def _blocked_smem_bytes(n: int, cfg: int) -> int:
    NB, CT = _BLOCKED_CFG.get(cfg, (32, 64))
    TPB = 256
    redsz = max(8 * NB, TPB)
    fcount = n * NB + NB * NB + n * CT + 2 * NB * CT + NB + redsz + NB + 8
    return fcount * 4


def _qr_cuda_blocked(a: torch.Tensor, cfg: int = 0) -> output_t:
    B, n, _ = a.shape
    props = torch.cuda.get_device_properties(a.device)
    # Defensive: if the chosen config exceeds this device's smem opt-in budget,
    # fall back to the reference path rather than launch-fail into garbage.
    smem_cap = getattr(props, "shared_memory_per_block_optin", 0) or 227000
    if _blocked_smem_bytes(n, cfg) > smem_cap:
        return torch.geqrf(a)
    H = torch.empty_like(a)
    Acm = torch.empty_like(a)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    num_sms = props.multi_processor_count
    grid = min(num_sms, B)
    if grid < 1:
        grid = 1
    _get_cuda_mod().qr_blocked_launch(
        a.data_ptr(), Acm.data_ptr(), H.data_ptr(), tau.data_ptr(),
        B, n, grid, cfg)
    return H, tau


def _coop_nb(n: int) -> int:
    # Panel width NB. Measured optimum (coop2 nb sweep): NB=16 wins at n=1024
    # (39.2k vs nb32 43.4k) and n=2048 (64.4k vs nb24 66.6k) -- a narrow panel
    # keeps the B-block panel kernel cheap, and its extra trailing HBM is offset.
    # NB=8 for n>3000 where (n x 16) panel sub-panel overflows the ~200KB smem.
    if n * 16 * 4 <= 200000:
        return 16
    return 8


def _qr_cuda_coop(a: torch.Tensor, nb: int = 0) -> output_t:
    # Multi-CTA cooperative blocked QR for large n (matrix does not fit smem,
    # tiny batch). All CTAs cooperate on ONE matrix at a time; loop the few
    # matrices in the batch. Block 0 factors each NB-wide panel ON-CHIP (active
    # sub-panel resident in smem), builds compact-WY T; all CTAs then grid-stride
    # the column-independent trailing update. Cross-CTA sync is a hand-rolled
    # atomic barrier on the default execution queue (grid sized to one-wave occupancy).
    B, n, _ = a.shape
    if nb <= 0:
        nb = _coop_nb(n)
    H = torch.empty_like(a)
    Acm = torch.empty((n, n), device=a.device, dtype=torch.float32)
    Tg = torch.empty((nb, nb), device=a.device, dtype=torch.float32)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    gbar = torch.zeros(2, device=a.device, dtype=torch.int32)
    mod = _get_cuda_mod()
    for b in range(B):
        gbar.zero_()
        mod.qr_coop_launch(
            a[b].data_ptr(), Acm.data_ptr(), H[b].data_ptr(), tau[b].data_ptr(),
            Tg.data_ptr(), gbar.data_ptr(), n, nb, 0)
    return H, tau


def _qr_cuda_coop2(a: torch.Tensor, nb: int = 0) -> output_t:
    # Batched two-kernel blocked QR for large n: panel factor (B blocks, one per
    # matrix, big smem) and trailing update (large grid, tiny smem, grid-strided
    # over (matrix, column-tile)) run as separate launches -- the launch boundary
    # is the cross-CTA barrier, so NO atomics and no co-residency constraint.
    # Fixes the grid-barrier megakernel's 12.5%-occupancy / 1-block-per-SM wall.
    B, n, _ = a.shape
    if nb <= 0:
        nb = _coop_nb(n)
    H = torch.empty_like(a)
    Acm = torch.empty((B, n, n), device=a.device, dtype=torch.float32)
    Tg = torch.empty((B, nb, nb), device=a.device, dtype=torch.float32)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    mod = _get_cuda_mod()
    mod.qr_coop2_launch(
        a.data_ptr(), Acm.data_ptr(), H.data_ptr(), tau.data_ptr(),
        Tg.data_ptr(), B, n, nb)
    return H, tau


# Trailing-update tile shapes for the Triton tf32x3 kernels, micro-swept on the
# dominant B=640 n=512 row-major panel (rank-16 trailing). The apply (delta=
# Vrow@YT, disjoint output tiles) wins SMALL: BM=64, BNc=32, 2 warps -- low warp
# count maximises occupancy on the thin rank-16 subtract (BM=128/4w regressed).
# YT (W=V^T@C reduces over tall pheight) likes BM=32, BNc=64, 2 warps.
_TC_YT = (32, 64, 2)        # (BM, BNc, num_warps)
_TC_APPLY = (64, 32, 2)


def _qr_cuda_coop2_tc(a: torch.Tensor, nb: int = 0, wide: bool = False) -> output_t:
    # coop2 with a TENSOR-CORE (tf32x3) trailing update. The CUDA panel kernel
    # (exact FP32 Householder + compact-WY T, on-chip) and transposes are kept;
    # only the trailing block-reflector update -- 85% of GPU time and previously
    # an FP32-SIMT ~1 TFLOP/s GEMM -- is replaced with two Triton tf32x3 tl.dot
    # kernels reading the column-major Acm in place. The Python loop alternates
    # CUDA panel -> Triton trailing; each kernel launch is the cross-CTA barrier.
    # wide=True uses the two-level IB=8 wide-panel factor so an nb=16/32 panel
    # fits smem at n=4096 (flat (n-p)*nb panel would overflow the 227KB opt-in).
    B, n, _ = a.shape
    if nb <= 0:
        nb = _coop_nb(n)
    H = torch.empty_like(a)
    Acm = torch.empty((B, n, n), device=a.device, dtype=torch.float32)
    Tg = torch.empty((B, nb, nb), device=a.device, dtype=torch.float32)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    YT = torch.empty((B, nb, n), device=a.device, dtype=torch.float32)
    mod = _get_cuda_mod()

    s_ab, s_ac, s_ar = Acm.stride(0), Acm.stride(1), Acm.stride(2)
    s_tb, s_tl, s_ti = Tg.stride(0), Tg.stride(1), Tg.stride(2)
    s_yb, s_yk, s_yc = YT.stride(0), YT.stride(1), YT.stride(2)
    BM_Y, BNc_Y, NW_Y = _TC_YT
    BM_A, BNc_A, NW_A = _TC_APPLY

    mod.qr_coop2_transpose_in(a.data_ptr(), Acm.data_ptr(), B, n)
    p = 0
    while p < n:
        cur_nb = nb if p + nb <= n else n - p
        if wide:
            mod.qr_coop2_wpanel(Acm.data_ptr(), Tg.data_ptr(), tau.data_ptr(),
                                B, n, nb, p, cur_nb)
        else:
            mod.qr_coop2_panel(Acm.data_ptr(), Tg.data_ptr(), tau.data_ptr(),
                               B, n, nb, p, cur_nb)
        jb = p + cur_nb
        ncols = n - jb
        if ncols > 0:
            nct_y = triton.cdiv(ncols, BNc_Y)
            _coop_trailing_YT_cm[(nct_y, B)](
                Acm, Tg, YT,
                B, n, p, cur_nb, ncols, jb,
                s_ab, s_ac, s_ar, s_tb, s_tl, s_ti, s_yb, s_yk, s_yc,
                BLK=nb, BM=BM_Y, BNc=BNc_Y, num_warps=NW_Y,
            )
            nct_a = triton.cdiv(ncols, BNc_A)
            nrt_a = triton.cdiv(n - p, BM_A)
            _coop_trailing_apply_cm[(nrt_a * nct_a, B)](
                Acm, YT,
                B, n, p, cur_nb, ncols, jb,
                s_ab, s_ac, s_ar, s_yb, s_yk, s_yc,
                BLK=nb, BM=BM_A, BNc=BNc_A, num_warps=NW_A,
            )
        p += cur_nb
    mod.qr_coop2_transpose_out(Acm.data_ptr(), H.data_ptr(), B, n)
    return H, tau


def _qr_cuda_coop2_tc_rm(a: torch.Tensor, nb: int = 16) -> output_t:
    # TRANSPOSE-FREE tf32x3 coop2: the CUDA panel factor and the Triton trailing
    # both operate on row-major A IN PLACE, so the two layout-shuffling transpose
    # kernels (qr_transpose_in/out, ~18% of n=512 GPU time) are eliminated. The
    # output H IS the factored A (geqrf packing). Triton kernels are layout-
    # agnostic: we pass A's row-major strides (column stride 1, row stride n).
    B, n, _ = a.shape
    H = a.clone()                       # factor in place; H is the row-major output
    Tg = torch.empty((B, nb, nb), device=a.device, dtype=torch.float32)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    YT = torch.empty((B, nb, n), device=a.device, dtype=torch.float32)
    mod = _get_cuda_mod()

    # H is row-major (B,n,n): element(row r,col c) at H[b,r,c].  For the Triton
    # kernels' (s_ac=col stride, s_ar=row stride): col stride = 1, row stride = n.
    s_ab = H.stride(0)
    s_ac = H.stride(2)                  # move one column == last dim == 1
    s_ar = H.stride(1)                  # move one row == n
    s_tb, s_tl, s_ti = Tg.stride(0), Tg.stride(1), Tg.stride(2)
    s_yb, s_yk, s_yc = YT.stride(0), YT.stride(1), YT.stride(2)
    BM_Y, BNc_Y, NW_Y = _TC_YT
    BM_A, BNc_A, NW_A = _TC_APPLY

    p = 0
    while p < n:
        cur_nb = nb if p + nb <= n else n - p
        mod.qr_coop2_panel_rm(H.data_ptr(), Tg.data_ptr(), tau.data_ptr(),
                              B, n, nb, p, cur_nb)
        jb = p + cur_nb
        ncols = n - jb
        if ncols > 0:
            nct_y = triton.cdiv(ncols, BNc_Y)
            _coop_trailing_YT_cm[(nct_y, B)](
                H, Tg, YT,
                B, n, p, cur_nb, ncols, jb,
                s_ab, s_ac, s_ar, s_tb, s_tl, s_ti, s_yb, s_yk, s_yc,
                BLK=nb, BM=BM_Y, BNc=BNc_Y, num_warps=NW_Y,
            )
            nct_a = triton.cdiv(ncols, BNc_A)
            nrt_a = triton.cdiv(n - p, BM_A)
            _coop_trailing_apply_cm[(nrt_a * nct_a, B)](
                H, YT,
                B, n, p, cur_nb, ncols, jb,
                s_ab, s_ac, s_ar, s_yb, s_yk, s_yc,
                BLK=nb, BM=BM_A, BNc=BNc_A, num_warps=NW_A,
            )
        p += cur_nb
    return H, tau


def _qr_cuda_coop3(a: torch.Tensor, nb: int = 32) -> output_t:
    # Two-level wide-panel batched QR: the panel kernel factors an NB-wide panel
    # via IB=8 inner sub-blocks (smem-resident) so NB can be large (32/48/64)
    # even when (n-p)*NB would overflow smem. Large NB cuts the trailing kernel's
    # C re-reads (n/NB passes -> HBM ~1/NB), the dominant cost at n=4096.
    B, n, _ = a.shape
    H = torch.empty_like(a)
    Acm = torch.empty((B, n, n), device=a.device, dtype=torch.float32)
    Tg = torch.empty((B, nb, nb), device=a.device, dtype=torch.float32)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    mod = _get_cuda_mod()
    mod.qr_coop3_launch(
        a.data_ptr(), Acm.data_ptr(), H.data_ptr(), tau.data_ptr(),
        Tg.data_ptr(), B, n, nb)
    return H, tau


# Max n for which n*n + slack floats fit in 227KB smem.
# (227328 - (256+256+4)*4) / 4 ~= 56300 -> n <= 237. Use 224 for headroom.
_SMEM_MAX_N = 224

# Compile the CUDA extension eagerly at import so build-time surfaces errors.
_get_cuda_mod()


def custom_kernel(data: input_t) -> output_t:
    a = data
    n = a.shape[-1]
    if n <= 64:
        return _qr_triton(a.contiguous())
    # n=65..127: the single-block-per-matrix blocked compact-WY kernel still wins
    # (too small for the tf32x3 panel/trailing launch overhead to pay off).
    if n < 128:
        return _qr_cuda_blocked(a.contiguous(), 5)  # NB16 CT128
    # n >= 128: batched two-kernel blocked QR with a TENSOR-CORE (tf32x3) trailing
    # update. The trailing block-reflector GEMM was 85% of GPU time as an FP32-
    # SIMT ~1 TFLOP/s kernel; tf32x3 tl.dot runs it on tensor cores at ~FP32
    # accuracy. nb=16 keeps the CUDA panel sub-panel in smem (ldp*16*4 <= 227KB
    # for n<=2048) and gives the apply MMA a valid K=16. n=176 measured -18% vs
    # the blocked kernel on the TC row-major path.
    if n <= 1024:
        # Transpose-free row-major path: drops both transpose kernels (~18%).
        # Wins at n<=1024; at n=2048 the row-major strided panel loads coalesce
        # worse than the column-major scratch, so n=2048 keeps the CM path.
        return _qr_cuda_coop2_tc_rm(a.contiguous(), nb=16)
    if n <= 2048:
        return _qr_cuda_coop2_tc(a.contiguous(), nb=16)
    # n>=4096 with the tiny batches this set uses (B=1,2): my 1-block-per-matrix
    # panel runs on only B SMs (98% of the GPU idle), so it is ~2x SLOWER than
    # cuSOLVER's geqrf, which parallelizes a single large QR across the device
    # (measured n=4096 B=2: mine 108ms vs geqrf 54ms). geqrf IS the reference
    # (exact H,tau), so for the large-n/tiny-batch regime route to it. At n<=2048
    # my batched kernel beats geqrf 3.6-93x and stays. Larger batches at n>2048
    # (B*n big -> panel no longer SM-starved) keep the wide-panel tf32x3 path.
    if a.shape[0] <= 8:
        return torch.geqrf(a)
    return _qr_cuda_coop2_tc(a.contiguous(), nb=16, wide=True)

