    cudaFuncSetAttribute(qr_panel_kernel<TPB, NBMAX, RM, UNR>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)((size_t)n * NBMAX * sizeof(float)));
    size_t panel_sh = (size_t)(n - p) * nb * sizeof(float);
